// ---------- check command (S4): every request must produce exactly one audit row.
function decisions(){const f=path.join(state,'model-decisions.jsonl');return fs.existsSync(f)?fs.readFileSync(f,'utf8').trim().split(/\r?\n/).filter(Boolean).map(JSON.parse):[];}
function checked(args,code,env={}){const before=decisions().length,r=runCli(['check',...args,'--json'],{FACTORY_ACTOR_ID:'fixture-actor',...env});assert.equal(r.status,code,r.stderr);const rows=decisions();assert.equal(rows.length,before+1,'exactly one decision row');const row=rows.at(-1),result=JSON.parse(r.stdout);for(const f of ['at','project','key','purpose','actor','decision','reasons','snapshotHash','profileHash','evidenceRefs','premiumJustification','actualConfirmation'])assert.ok(Object.hasOwn(row,f),f);assert.equal(row.actor,'fixture-actor');assert.equal(row.decision,result.decision);assert.equal(result.permitted,code===0);assert.equal(result.dispatchAuthorized,code===0&&row.purpose!=='verify');return {r,row,result};}
function checkArgs(purpose='cli-run',p=routeProfile(),target=key){const f=path.join(root,'check-profile.json');write(f,p);return [project,target,'--purpose',purpose,'--profile',f];}
function actualFixture(overrides={}){const r=routeCli();assert.equal(r.status,0,r.stderr);const receipt=JSON.parse(r.stdout);return {engine:'fixture-engine',model:'small',effort:null,sourceRef:'fixtures/original-provider-ack.json',receiptPath:receipt.file,confirmation:'provider-ack',...overrides};}
function verifyArgs(actual,p=routeProfile()){const f=path.join(root,'actual.json');write(f,actual);return [...checkArgs('verify',p),'--actual',f];}
for(const purpose of ['native-delegation','cli-run','route'])test('check '+purpose+' permits known worker and appends one attributed decision',()=>{const s=routeFixture(),p=routeProfile(),v=checked(checkArgs(purpose,p),0);assert.equal(v.row.project,project);assert.equal(v.row.key,key);assert.equal(v.row.purpose,purpose);assert.equal(v.row.snapshotHash,s.hash);assert.equal(v.row.profileHash,H(p));assert.equal(v.row.actualConfirmation,'unknown');assert.ok(v.row.evidenceRefs.length);});
