// ---------- history-aware audit (S5), using actual file/receipt/snapshot links.
function historicalRun({tier='worker',authorized=true,actual=true,botId='fixture-bot',costUsd=1,costSource='reported',input=10,output=5,tokensReported=true}={}){
  routeFixture();const policyFile=path.join(state,'route-policy.json'),policy=JSON.parse(fs.readFileSync(policyFile));policy.projects[project].allowlist=authorized?[key]:[];write(policyFile,policy);
  const evidenceFile=path.join(state,'provider-evidence.json'),e=JSON.parse(fs.readFileSync(evidenceFile));e.records.find(r=>r.field==='tier').value.normalized=tier;write(evidenceFile,e);sleepPastMtimeGranularity();const snap=takeSnapshot(project);
  const tag=require('node:crypto').randomUUID(),snapshotFile=path.join(state,'archived-snapshots',tag+'.json'),receiptFile=path.join(state,'receipts',tag+'.json');write(snapshotFile,snap);
  const receipt={mode:'project',project,decidedAt:new Date().toISOString(),choice:{key,engine:'fixture-engine',model:'small'},dispatchAuthorized:authorized,providerSnapshot:{path:snapshotFile,hash:snap.hash,observedAt:snap.observedAt},actual:actual?{engine:'fixture-engine',model:'small',effort:null,confirmedBy:'engine:fixtures/original-ack.json'}:{engine:null,model:null,effort:null,confirmedBy:'unconfirmed'}};write(receiptFile,receipt);
  return {at:new Date().toISOString(),botId,threadId:'usage-'+tag,instanceId:'fixture-engine',model:'small',input,output,tokensReported,costUsd,costSource,receiptPath:receiptFile};
}
function auditCli(flags=[]){return runCli(['audit',project,'--section','Fixture','--json',...flags]);}
function ledger(rows,file='2026-11.jsonl'){write(path.join(home,'usage',file),rows.map(r=>JSON.stringify(r)).join('\n')+'\n');}
test('audit separates historical authorization/tier, current comparison, attribution and measurement coverage exactly',()=>{
  const premium=historicalRun({tier:'premium',costUsd:2,input:80,output:20});
  const unauthorized=historicalRun({authorized:false,costUsd:3,costSource:'estimated',input:40,output:10});
  const removed=historicalRun({botId:'removed-bot',costUsd:7,input:30,output:10});
  const noProof={...premium,receiptPath:undefined,costUsd:5,input:15,output:5};
  const unknownActual={...premium,costUsd:null,tokensReported:false,input:0,output:0};const receipt=JSON.parse(fs.readFileSync(premium.receiptPath));receipt.actual={engine:'fixture-engine',model:'small',confirmedBy:'hattera:ledger-fallback'};unknownActual.receiptPath=path.join(state,'receipts','unknown-actual.json');write(unknownActual.receiptPath,receipt);
  const exception={...noProof,botId:'exception-bot',costUsd:null,input:0,output:0,tokensReported:false};
  const botFile=path.join(home,'bots.json'),bots=JSON.parse(fs.readFileSync(botFile));bots.push({id:'exception-bot',section:'Fixture'},{id:'other-bot',section:'Other'});write(botFile,bots);
  const pf=path.join(state,'route-policy.json'),p=JSON.parse(fs.readFileSync(pf));p.projects[project].allowlist=[];p.projects[project].modelDecisions={[key]:{tier:'worker'}};p.knownExceptions=[{botId:'exception-bot',reason:'documented bootstrap exception only'}];write(pf,p);
  ledger([premium,unauthorized,noProof],'2026-10.jsonl');ledger([unknownActual,removed,exception,{...premium,botId:'other-bot'}]);ledger([{...premium,costUsd:999}],'2026-09.jsonl');
  const native=bytes(home),policyBefore=fs.readFileSync(pf,'utf8');fs.unlinkSync(path.join(state,'route-identities.json'));const r=auditCli();assert.equal(r.status,7,r.stderr);const a=JSON.parse(r.stdout);
  assert.equal(a.schema,2);assert.equal(a.rows.length,6);assert.deepEqual(a.authorizationAtRun,{authorized:2,unauthorized:1,unknown:3});assert.deepEqual(a.tierAtRun,{worker:2,premium:1,unknown:3});assert.deepEqual(a.actualIdentity,{confirmed:3,unknown:3});assert.deepEqual(a.attribution,{section:5,unknown:1});assert.equal(a.currentPolicyComparison.notAllowlisted,6);
  assert.deepEqual(a.costSources,{reported:{rows:3,usd:14},estimated:{rows:1,usd:3},unreported:{rows:2,usd:null}});
  assert.equal(a.tokens.total,210);assert.equal(a.tokens.tokensReportedFalse,2);assert.equal(a.premiumCoverage.eligibleRows,2);assert.deepEqual(a.premiumCoverage.tokens,{eligible:150,premium:100,share:2/3});assert.equal(a.premiumCoverage.reportedCost.eligible,2);assert.equal(a.premiumCoverage.reportedCost.premium,2);assert.equal(a.premiumCoverage.estimatedCost.eligible,3);
  assert.equal(a.coveredRange.earlierFilesOmitted,1);assert.equal(a.coveredRange.missingEarlierHistory,true);assert.deepEqual(a.coveredRange.files,['2026-10.jsonl','2026-11.jsonl']);assert.equal(a.filters.otherSectionRowsExcluded,1);
  const er=a.rows.find(r=>r.botId==='exception-bot');assert.equal(er.authorizationAtRun,'unknown');assert.deepEqual(er.knownExceptionReasons,['documented bootstrap exception only']);assert.ok(a.groups.some(g=>g.attribution==='unknown'));
  assert.deepEqual(JSON.parse(fs.readFileSync(a.file)),a);assert.equal(a.dispatchAuthorized,false);assert.deepEqual(bytes(home),native);assert.equal(fs.readFileSync(pf,'utf8'),policyBefore);
});
test('audit clean historical evidence remains clean despite stale current catalog and changed tier policy',()=>{const record=historicalRun({tier:'premium',costUsd:4,input:20,output:10});ledger([record]);const f=path.join(state,'route-policy.json'),p=JSON.parse(fs.readFileSync(f));p.projects[project].modelDecisions={[key]:{tier:'worker'}};write(f,p);const old=new Date(Date.now()-72*3600000);fs.utimesSync(path.join(home,'providers/engine-models/fixture-engine.json'),old,old);fs.unlinkSync(path.join(state,'route-identities.json'));const r=auditCli();assert.equal(r.status,0,r.stderr);const a=JSON.parse(r.stdout);assert.equal(a.rows[0].tierAtRun,'premium');assert.equal(a.rows[0].currentPolicyComparison.tierClaim,'worker');assert.deepEqual(a.authorizationAtRun,{authorized:1,unauthorized:0,unknown:0});assert.equal(a.premiumCoverage.reportedCost.share,1);assert.equal(a.findings.length,0);});
test('audit never replaces missing historical proof with the current snapshot or exception',()=>{const row=historicalRun();delete row.receiptPath;ledger([row]);const r=auditCli();assert.equal(r.status,7,r.stderr);const a=JSON.parse(r.stdout);assert.equal(a.rows[0].authorizationAtRun,'unknown');assert.equal(a.rows[0].tierAtRun,'unknown');assert.equal(a.premiumCoverage.tokens.share,null);});
test('audit explicit session link works only for a unique project receipt',()=>{const row=historicalRun(),receipt=JSON.parse(fs.readFileSync(row.receiptPath));receipt.sessionId='session-audit';write(row.receiptPath,receipt);delete row.receiptPath;row.sessionId='session-audit';ledger([row]);assert.equal(auditCli().status,0);write(path.join(state,'receipts','ambiguous.json'),receipt);const r=auditCli();assert.equal(r.status,7);assert.match(JSON.parse(r.stdout).rows[0].findings.join('; '),/ambiguous/);});
test('audit malformed since/arguments exits2 and writes no report',()=>{commandSetup();const before=stateBytes();assert.equal(auditCli(['--since','not-a-date']).status,2);for(const flags of [['--since'],['--since','--section','Other'],['--section','Fixture']])assert.equal(auditCli(flags).status,2);assert.equal(runCli(['audit',project,'--json']).status,2);assert.deepEqual(stateBytes(),before);});
test('audit since filters rows without changing the explicit two-file coverage',()=>{const row=historicalRun();ledger([row]);const since=new Date(Date.parse(row.at)+1000).toISOString(),r=auditCli(['--since',since]);assert.equal(r.status,0,r.stderr);const a=JSON.parse(r.stdout);assert.equal(a.rows.length,0);assert.equal(a.filters.beforeSinceRowsExcluded,1);assert.equal(a.premiumCoverage.tokens.share,null);});
test('audit a present bot with no section is unknown attribution, never silently omitted',()=>{const row=historicalRun();ledger([row]);const f=path.join(home,'bots.json'),bots=JSON.parse(fs.readFileSync(f));delete bots[0].section;write(f,bots);const r=auditCli();assert.equal(r.status,7,r.stderr);const a=JSON.parse(r.stdout);assert.equal(a.rows.length,1);assert.equal(a.rows[0].attribution,'unknown');assert.equal(a.filters.otherSectionRowsExcluded,0);assert.equal(a.premiumCoverage.eligibleRows,0);});
test('audit conflicting explicit session cannot fall back to a matching thread',()=>{const row=historicalRun(),receipt=JSON.parse(fs.readFileSync(row.receiptPath));receipt.sessionId='original-session';receipt.threadId=row.threadId;write(row.receiptPath,receipt);const direct={...row,sessionId:'wrong-session'};ledger([direct]);assert.equal(auditCli().status,7);delete direct.receiptPath;ledger([direct]);const r=auditCli();assert.equal(r.status,7,r.stderr);assert.equal(JSON.parse(r.stdout).rows[0].authorizationAtRun,'unknown');direct.sessionId='original-session';ledger([direct]);assert.equal(auditCli().status,0);});
test('audit malformed native JSON fails2 without exposing ignored private fields',()=>{commandSetup();write(path.join(home,'bots.json'),'[{"ignored":"AUDIT_PRIVATE_CANARY\\q"}]');const r=auditCli();assert.equal(r.status,2);assert.ok(!r.stdout.includes('AUDIT_PRIVATE_CANARY'));assert.ok(!r.stderr.includes('AUDIT_PRIVATE_CANARY'));});
for(const [name,change,code] of [
 ['before snapshot observation',(receipt,snapshot,row)=>receipt.decidedAt=new Date(Date.parse(snapshot.observedAt)-60000).toISOString(),7],
 ['after usage',(receipt,snapshot,row)=>receipt.decidedAt=new Date(Date.parse(row.at)+60000).toISOString(),7],
 ['at snapshot observation',(receipt,snapshot,row)=>receipt.decidedAt=snapshot.observedAt,0],
 ['valid original decision',()=>{},0],
])test('audit historical chronology: '+name,()=>{const row=historicalRun({tier:'premium',costUsd:6,input:70,output:20}),file=row.receiptPath,receipt=JSON.parse(fs.readFileSync(file)),snapshot=JSON.parse(fs.readFileSync(receipt.providerSnapshot.path));change(receipt,snapshot,row);write(file,receipt);ledger([row]);const r=auditCli();assert.equal(r.status,code,r.stderr);const a=JSON.parse(r.stdout),historical=a.rows[0];assert.equal(a.tokens.total,90);assert.deepEqual(a.costSources.reported,{rows:1,usd:6});assert.equal(a.actualIdentity.confirmed,1);assert.equal(historical.currentPolicyComparison.allowlisted,true);if(code===7){assert.equal(historical.authorizationAtRun,'unknown');assert.equal(historical.tierAtRun,'unknown');assert.match(historical.findings.join('; '),/not contemporaneous/);assert.equal(a.premiumCoverage.eligibleRows,0);assert.equal(a.premiumCoverage.unknownTierRows,1);assert.deepEqual(a.premiumCoverage.tokens,{eligible:null,premium:null,share:null});assert.equal(a.premiumCoverage.reportedCost.eligible,null);}else{assert.equal(historical.authorizationAtRun,'authorized');assert.equal(historical.tierAtRun,'premium');assert.equal(a.premiumCoverage.tokens.share,1);assert.equal(a.findings.length,0);}});

// S3B: route must hold exactly where check holds; unresolved tier/price is never cleared by cost ranking.
for(const [name,opts] of [['unknown tier',{tier:false}],['unresolved price',{price:false}]])test('S3B route holds8 for '+name+' like check, with no choice and no permission in stdout or receipt',()=>{
  const s=routeFixture(opts);const c=checked(checkArgs('route'),8);assert.ok(c.result.reasons.length);
  const r=routeCli();assert.equal(r.status,8,r.stderr);const v=JSON.parse(r.stdout);
  assert.equal(v.dispatchAuthorized,false);assert.equal(v.choice,null);assert.equal(v.providerSnapshot.hash,s.hash);assert.ok(v.unknowns.length);assert.equal(v.premiumJustification,null);
  const saved=JSON.parse(fs.readFileSync(v.file,'utf8'));assert.equal(saved.dispatchAuthorized,false);assert.equal(saved.choice,null);assert.deepEqual(v.fallbacks,[]);
});
test('S3B positive control: resolved tier and price still route with exit0 and permission',()=>{routeFixture();const r=routeCli();assert.equal(r.status,0,r.stderr);const v=JSON.parse(r.stdout);assert.equal(v.dispatchAuthorized,true);assert.equal(JSON.parse(fs.readFileSync(v.file,'utf8')).dispatchAuthorized,true);});

